"""WP7T follow-up: copy from the OOD-C snapshots the files WP7T traces touched that WP7R's extract lacks.  Owner: Claude.
Same matching as scripts/weight_edit/wp7_extract_files.py; the WP7T kernel's own extract step left an empty tar.
CPU only. Output: /kaggle/working/wp7t_files.tgz (wp7t_files/oodc/<iid>/<path> + report.json)."""
import glob, json, os, tarfile, traceback
from pathlib import Path
NEED = json.loads(NEED_JSON)
hits = glob.glob("/kaggle/input/**/oodc_set/tasks.jsonl", recursive=True)
print("tasks.jsonl", hits, flush=True)
SNAP = Path(hits[0]).parent / "snapshots"
print("snapshots dir", SNAP, SNAP.is_dir(), len(list(SNAP.glob("*.tgz"))) if SNAP.is_dir() else 0, flush=True)
OUT = Path("/tmp/wp7t_files/oodc")
OUT.mkdir(parents=True, exist_ok=True)
report = {}
for iid, rels in sorted(NEED.items()):
    tgz = SNAP / f"{iid}.tgz"
    if not tgz.exists():
        report[iid] = {"got": 0, "missing": rels, "no_snapshot": True}; continue
    try:
        got, missing = 0, []
        with tarfile.open(tgz) as tf:
            members = {m.name.removeprefix("./"): m for m in tf.getmembers() if m.isfile()}
            for rel in sorted(rels):
                cand = [k for k in members if k.endswith("/" + rel)]
                m = members.get(rel) or (members[min(cand, key=len)] if cand else None)
                if m is None:
                    missing.append(rel); continue
                dst = OUT / iid / rel
                dst.parent.mkdir(parents=True, exist_ok=True)
                dst.write_bytes(tf.extractfile(m).read())
                got += 1
        report[iid] = {"got": got, "missing": missing}
    except Exception as e:
        report[iid] = {"got": 0, "missing": rels, "error": repr(e)}
        traceback.print_exc()
(OUT / "report.json").write_text(json.dumps(report, indent=1))
print("tasks", len(report), "files", sum(r["got"] for r in report.values()),
      "missing", sum(len(r["missing"]) for r in report.values()),
      "errors", sum("error" in r for r in report.values()), flush=True)
with tarfile.open("/kaggle/working/wp7t_files.tgz", "w:gz") as t:
    t.add("/tmp/wp7t_files", arcname="wp7t_files")
print("done", os.path.getsize("/kaggle/working/wp7t_files.tgz"), flush=True)
